export async function renderVerification(main,e,icon){
  const [core,demo,browser]=await Promise.all(['core-tests.json','demo-tests.json','browser-checks.json'].map(p=>fetch('/'+p).then(r=>{if(!r.ok)throw new Error('测试记录加载失败');return r.json();})));
  const suites=[core,demo],total=suites.reduce((n,s)=>n+s.total,0),passed=suites.reduce((n,s)=>n+s.passed,0),failed=suites.reduce((n,s)=>n+s.failed,0);
  const label=name=>({test_exactly_twenty_questions_with_three_points:'题库20道题、每题3个要点',test_partial_correct_is_not_mastery:'部分正确按要点计分，不判掌握',test_unsupported_question_is_refused:'域外问题拒答',test_forged_page_and_nonexistent_excerpt_fail_validation:'虚构页码与摘录校验',test_full_recovery_loop_remains_conservative:'补学再测闭环保持保守评价',test_repeated_submission_is_idempotent:'重复提交不重复记账',test_student_data_is_partitioned:'本地版学习身份隔离',test_windows_https_fallback_never_evaluates_query_as_script:'Windows兼容请求不执行查询文本'}[name.split('.').at(-1)]||name.split('.').at(-1).replace(/^test_/,'').replaceAll('_',' '));
  main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">VERIFICATION · MEASURED, NOT ASSUMED</div><h1>测试情况，可以逐项核对。</h1><p class="subheading">工程回归、浏览器实测与尚未验证的内容分别记录。测试通过不等于医学准确率。</p></div><a class="btn btn-light" href="/测试情况.md" download>${icon('download')}下载测试说明</a></div><div class="report-top"><div class="stat-card"><div class="stat-icon">${icon('check')}</div><div><b>${passed}<span class="count-small">/ ${total}</span></b><span>自动化测试通过</span></div></div><div class="stat-card"><div class="stat-icon green">${icon('target')}</div><div><b>${failed}</b><span>自动化测试失败</span></div></div><div class="stat-card"><div class="stat-icon orange">${icon('layers')}</div><div><b>20<span class="count-small">道题</span></b><span>脑神经 · 10个知识点</span></div></div></div><div class="intro-strip">${icon('info')}公开演示在浏览器保存数据；Python本地版使用SQLite。下面分别报告两套实现的实际测试，未把本地版通过直接当成在线版通过。</div><div class="report-layout"><div>${suites.map(s=>`<section class="panel"><div class="section-title"><h2>${s===core?'Python 本地版回归':'在线演示引擎回归'}</h2><span class="pill green">${s.passed} / ${s.total} 通过</span></div><p class="hint">实际运行时间：${e(new Date(s.tested_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}))}（北京时间） · 耗时 ${(s.duration_ms/1000).toFixed(2)} 秒</p><details><summary class="hint">展开逐项测试记录</summary><div class="table-scroll"><table class="report-table"><thead><tr><th>测试项目</th><th>结果</th><th>耗时</th></tr></thead><tbody>${s.cases.map(c=>`<tr><td title="${e(c.name)}">${e(label(c.name))}</td><td><span class="pill ${c.status==='passed'?'green':'orange'}">${c.status==='passed'?'通过':e(c.status)}</span></td><td>${Number(c.duration_ms||0).toFixed(1)} ms</td></tr>`).join('')}</tbody></table></div></details><a class="btn-text" href="/${s===core?'core-tests.json':'demo-tests.json'}" target="_blank" rel="noopener">查看原始JSON记录 ${icon('link')}</a></section>`).join('')}<section class="panel"><div class="section-title"><h2>浏览器与联网实测</h2><span class="pill">${e(browser.edition)}</span></div><p class="hint">${e(browser.tested_at)} · ${e(browser.scope)}</p>${browser.checks.map(c=>`<div class="rubric-row ${c.status==='passed'?'pass':'fail'}"><div class="rubric-title"><strong>${e(c.name)}</strong><span class="pill ${c.status==='passed'?'green':'orange'}">${e(c.status==='passed'?'已验证':c.status==='limited'?'受限':'待验证')}</span></div><p>${e(c.evidence)}</p></div>`).join('')}</section></div><aside><section class="panel agent-panel"><div class="panel-title">${icon('spark')}3分钟演示建议</div><ol class="method-list"><li>进入动眼神经知识点。</li><li>只选对一个要点，观察33分与补学建议。</li><li>补学后完成不同情境的迁移题。</li><li>提出机制差异疑问，检索真实文献。</li><li>回到报告，核对首次与最近成绩。</li></ol><a class="btn btn-primary w-full" href="#courses">开始演示 ${icon('arrow')}</a></section><section class="panel"><div class="panel-title">${icon('shield')}尚未验证的部分</div><p class="hint">没有正式教学大纲与授权教材页码集，没有教师审核结论和真实学生学习效果实验。</p><p class="hint">当前成绩变化是学习过程记录，不是干预效果；未测量独立医学问答正确率、正式认知诊断效度或教学收益。</p><p class="hint">在线演示没有配置付费模型，因此不声称已验证生成式辅导。文献相关性与证据质量需要人工复核。</p></section><section class="panel"><div class="panel-title">${icon('book')}核对原始记录</div><a href="/core-tests.json" target="_blank" rel="noopener">Python回归记录</a><br><a href="/demo-tests.json" target="_blank" rel="noopener">在线引擎回归记录</a><br><a href="/browser-checks.json" target="_blank" rel="noopener">浏览器检查记录</a></section></aside></div>`;
}
